with base as (select *, unit_price * quantity as line_total from order_items where product_id in (23, 25, 39)), summary as (select case when line_total >= 65 then 'high' when line_total >= 28 then 'mid' else 'low' end as line_total_bucket, round(stddev(quantity), 2) as stddev_quantity from base group by case when line_total >= 65 then 'high' when line_total >= 28 then 'mid' else 'low' end) select line_total_bucket, stddev_quantity from summary order by line_total_bucket;
